using System.Text.Json;


// Provided: the HTTP layer is injected so tests can control it.
public interface IHttpGet { Task<string> GetAsync(string url); }
public sealed record Hotel(int Id, string Name, string City, decimal Price);

// Agoda — the online-assessment REST question, reconstructed: page through a JSON API and aggregate.
//   GET {baseUrl}?page=N  ->  {"page":N,"total_pages":T,"data":[{"id":1,"name":"…","city":"…","price":120.5}, …]}
public static class HotelClient {
    // S1: every hotel in `city` (case-insensitive), cheapest first, ties by id.
    // S2: a page that fails with HttpRequestException is retried, up to 3 attempts in total.
    public static Task<List<Hotel>> HotelsInCityAsync(IHttpGet http, string baseUrl, string city) => HotelsInCityAsync(http, baseUrl, city, 1);

    // S3: pages 2..T are fetched concurrently, never more than maxParallel requests in flight.
    public static async Task<List<Hotel>> HotelsInCityAsync(IHttpGet http, string baseUrl, string city, int maxParallel) {
        if (http == null) throw new ArgumentNullException(nameof(http));
        if (maxParallel <= 0) throw new ArgumentOutOfRangeException(nameof(maxParallel));
        var (total, first) = await PageAsync(http, baseUrl, 1);
        var all = new List<Hotel>(first);
        using var gate = new SemaphoreSlim(maxParallel);
        var tasks = Enumerable.Range(2, Math.Max(0, total - 1)).Select(async p => {
            await gate.WaitAsync();
            try { return (await PageAsync(http, baseUrl, p)).Items; }
            finally { gate.Release(); }
        }).ToList();
        foreach (var items in await Task.WhenAll(tasks)) all.AddRange(items);
        return all.Where(h => string.Equals(h.City, city, StringComparison.OrdinalIgnoreCase))
                  .OrderBy(h => h.Price).ThenBy(h => h.Id).ToList();
    }

    static async Task<(int Total, List<Hotel> Items)> PageAsync(IHttpGet http, string baseUrl, int page) {
        for (int attempt = 1; ; attempt++) {
            try {
                var json = await http.GetAsync(baseUrl + "?page=" + page);
                using var doc = JsonDocument.Parse(json);
                var root = doc.RootElement;
                int total = root.GetProperty("total_pages").GetInt32();
                var items = new List<Hotel>();
                foreach (var e in root.GetProperty("data").EnumerateArray())
                    items.Add(new Hotel(e.GetProperty("id").GetInt32(), e.GetProperty("name").GetString(),
                                        e.GetProperty("city").GetString(), e.GetProperty("price").GetDecimal()));
                return (total, items);
            }
            catch (HttpRequestException) when (attempt < 3) {
                await Task.Delay(10 * attempt);             // brief backoff before the retry
            }
        }
    }
}
